import{_ as s,C as r,o as n,c as h,a2 as t,E as a}from"./chunks/framework.9yf7n3zg.js";const i="/guide/media/manuscript-overview.webp",d="/guide/media/manuscript-script.webp",c="/guide/media/manuscript-trail.webp",l="/guide/media/manuscript-gutter.webp",p="/guide/media/manuscript-passage.webp",T=JSON.parse('{"title":"Manuscript","description":"","frontmatter":{},"headers":[],"relativePath":"guide/manuscript.md","filePath":"guide/manuscript.md","lastUpdated":1792171429000}'),g={name:"guide/manuscript.md"};function u(m,e,f,w,y,b){const o=r("Clip");return n(),h("div",null,[e[0]||(e[0]=t('<h1 id="manuscript" tabindex="-1">Manuscript <a class="header-anchor" href="#manuscript" aria-label="Permalink to &quot;Manuscript&quot;">​</a></h1><p>The manuscript view shows the whole story as one book, on one page that scrolls from the first line to the last. It is where you read your draft the way a reader meets it, see what the rest of Leathercase knows about any passage, leave comments, and jump back into your own writing app at the exact place you want to change. The page is read only. Leathercase never writes into your chapters: to change a sentence, you open it in the software you write in.</p><p><img src="'+i+'" alt="The manuscript of The Lamp at Ferrol: the position bar at the top, Act I as a heading, the chapter The Night the Lamp Went Out with its scene The cottage, and the side column on the right" width="1130" height="900" loading="lazy"></p><h2 id="opening-the-manuscript" tabindex="-1">Opening the manuscript <a class="header-anchor" href="#opening-the-manuscript" aria-label="Permalink to &quot;Opening the manuscript&quot;">​</a></h2><p>Open a story, then pick <strong>Manuscript</strong> under the story&#39;s name in the sidebar. You can also press <code>Ctrl+7</code> (<code>Cmd+7</code> on macOS), pick <strong>Manuscript</strong> from the view menu in the breadcrumb, or type &quot;Manuscript&quot; in the command palette (<code>Ctrl/Cmd+K</code>).</p><p>Other views send you here too, each to a precise place:</p><ul><li>A scene picked on the <a href="/guide/guide/plot-grid">plot grid</a>, in the <a href="/guide/guide/threads">threads</a> view or on a <a href="/guide/guide/characters">character&#39;s sheet</a> opens the page scrolled to that scene&#39;s heading.</li><li>A lens offered from elsewhere opens with that lens on. The <strong>Open the accents lens</strong> button on a character&#39;s <strong>Voice</strong> tab is one (see <a href="/guide/guide/lenses">Lenses and style checks</a>).</li><li><strong>Review</strong> beside a broken anchor on <a href="/guide/guide/desk">the Desk</a> opens the page with the review of the first broken anchor already showing (see <a href="#broken-anchors">Broken anchors</a>).</li><li>When a story&#39;s app has not been chosen yet and there are several that could open it, opening a file from elsewhere brings you to the manuscript first, so you can choose (see <a href="#open-in-your-own-app">Open in</a>).</li></ul><h2 id="what-the-page-shows" tabindex="-1">What the page shows <a class="header-anchor" href="#what-the-page-shows" aria-label="Permalink to &quot;What the page shows&quot;">​</a></h2><p>The page is the story in reading order, with no file names or outline panel between the parts. Leathercase builds it from your files as they are:</p><table tabindex="0"><thead><tr><th>On the page</th><th>Where it comes from</th></tr></thead><tbody><tr><td>Part and act headings</td><td>Your folders. <code>Act I - The Dark Lamp</code> becomes a heading above its chapters.</td></tr><tr><td>Chapter headings</td><td>Each note&#39;s name, with sort prefixes such as <code>01 </code> taken off, so <code>01 The Night the Lamp Went Out.md</code> reads <strong>The Night the Lamp Went Out</strong>.</td></tr><tr><td>Scene headings</td><td>The headings inside a note (<code># The cottage</code>, <code># The tower</code>).</td></tr><tr><td>Paragraphs</td><td>The prose under them, with its emphasis shown as emphasis.</td></tr><tr><td>Scene breaks</td><td>A horizontal rule (<code>---</code>) in the note shows as a thin line.</td></tr></tbody></table><p>The order is the folder tree, the same order you see in your file manager: folders and notes sort by path, and numbers sort as numbers, so <code>Chapter 2</code> comes before <code>Chapter 10</code>. A note can set its own place with <code>story-order:</code> in its front matter; notes with a number come first, by number (see <a href="/guide/reference/front-matter#any-note">Front matter</a>).</p><p>Some notes never appear on the page:</p><ul><li>Every file that is not declared as the story&#39;s prose. Only prose makes the book: notes about the story&#39;s world (characters, places, items, factions, events and kinds of your own), plans, records, work notes, research, scraps and files still unsorted all stay out (see <a href="/guide/guide/how-a-story-is-read">How a story is read</a>). In The Lamp at Ferrol, <code>Characters/Nora Vidal.md</code> and <code>Places/Ferrol Point.md</code> stay out.</li><li>A note with <code>manuscript: false</code> in its front matter. The Lamp at Ferrol&#39;s project note, <code>The Lamp at Ferrol.md</code>, carries it.</li><li>A note with no prose at all, such as an outline that is only a list.</li><li>Files your story&#39;s patterns leave out, such as a folder you untick in the story&#39;s file tree (see <a href="/guide/guide/story-settings">Story settings</a>).</li></ul><p>A story written in a single file reads as that file&#39;s headings in order.</p><h3 id="how-the-book-is-cut-into-headings" tabindex="-1">How the book is cut into headings <a class="header-anchor" href="#how-the-book-is-cut-into-headings" aria-label="Permalink to &quot;How the book is cut into headings&quot;">​</a></h3><p>Four preferences in <strong>Settings › Manuscript</strong> change how the notes become one book. They change only the page; the files are read as they are. They are kept on this machine, in <code>preferences.json</code>.</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Folder levels as headings</strong></td><td>How many folder levels become headings above the notes; 0 for none.</td><td>2</td></tr><tr><td><strong>Note names as headings</strong></td><td>A note&#39;s name becomes a heading above its text.</td><td>On</td></tr><tr><td><strong>Strip from names</strong></td><td><strong>Numbers and separators</strong> drops sort prefixes such as <code>01 - </code> from folder and note names; <strong>Nothing</strong> keeps names as they are.</td><td>Numbers and separators</td></tr><tr><td><strong>Reading speed</strong></td><td>Words a minute, for the reading time in the position bar (100 to 600).</td><td>250</td></tr></tbody></table><h3 id="inline-emphasis" tabindex="-1">Inline emphasis <a class="header-anchor" href="#inline-emphasis" aria-label="Permalink to &quot;Inline emphasis&quot;">​</a></h3><p>The page shows the marks of your text as a reader would see them, not as their symbols:</p><table tabindex="0"><thead><tr><th>You wrote</th><th>The page shows</th></tr></thead><tbody><tr><td><code>*italic*</code> or <code>_italic_</code></td><td>italic</td></tr><tr><td><code>**bold**</code> or <code>__bold__</code></td><td>bold</td></tr><tr><td><code>==highlight==</code></td><td>highlighted text</td></tr><tr><td>a wiki link such as <code>[[02 The Ledger]]</code>, or one with an alias after a vertical bar</td><td>the alias when there is one, otherwise the note&#39;s name</td></tr><tr><td><code>[a link](https://…)</code></td><td>the link&#39;s text alone</td></tr><tr><td><code>%% a comment %%</code></td><td>nothing on the line; the comment is listed in the side column instead (see <a href="/guide/guide/comments">Comments and word lists</a>)</td></tr></tbody></table><p>Anything else stays as written. Quoted blocks (<code>&gt; …</code>) show as quotations.</p><h3 id="a-screenplay-on-the-page" tabindex="-1">A screenplay on the page <a class="header-anchor" href="#a-screenplay-on-the-page" aria-label="Permalink to &quot;A screenplay on the page&quot;">​</a></h3><p>A story written in Fountain, such as The Night Sleeper, shows as a script rather than as paragraphs. Sluglines are in capitals and action runs across the full width. Speech is indented as in a screenplay: the character&#39;s cue in capitals furthest in, a parenthetical under it, and the dialogue in a narrower column below. Transitions sit to the right, and centred text, lyrics, sections and synopses have their own styles. A Fountain title page shows its title at the top; a page break (<code>===</code>) shows as a line.</p><p>The lenses and the arrow keys do not read a script: they walk past it to the next prose note.</p><p><img src="'+d+'" alt="The Night Sleeper on the manuscript page, set as a script: a slugline, action across the page, and the speech indented, LUSK (V.O.) with the parenthetical (on the phone) under it and the dialogue in a narrower column" width="650" height="498" loading="lazy"></p><h3 id="the-position-bar" tabindex="-1">The position bar <a class="header-anchor" href="#the-position-bar" aria-label="Permalink to &quot;The position bar&quot;">​</a></h3><p>The head of the view, where other views show a state line, holds a thin bar that fills as you scroll, and a line beside it:</p><p><code>34% · 1,712 of 5,040 words · 20 min</code></p><p>That is how far down the book you are, the words above the top of the page out of the whole, and the time it takes to read the whole book at your reading speed. When the story has comments, the line adds them: <code>· 3 open of 5 comments</code>.</p><h3 id="the-trail-in-the-breadcrumb" tabindex="-1">The trail in the breadcrumb <a class="header-anchor" href="#the-trail-in-the-breadcrumb" aria-label="Permalink to &quot;The trail in the breadcrumb&quot;">​</a></h3><p>As you scroll, the breadcrumb at the top of the window grows a trail after <strong>Manuscript</strong>: the part and the chapter at the top of the page, for example <code>Act II - Salvage › The Reef › The boat</code>. Each piece is a way back up: click it and the page scrolls to that heading. At the very top of the book the trail is empty. When the title bar is too narrow for the whole path, its middle folds behind <code>…</code> at its start.</p><p><img src="'+c+'" alt="The breadcrumb while the page is scrolled into chapter five, folded to fit the window, with its … menu open on Sample, Act II - Salvage and The Reef" width="405" height="191" loading="lazy"></p><h3 id="the-gutter" tabindex="-1">The gutter <a class="header-anchor" href="#the-gutter" aria-label="Permalink to &quot;The gutter&quot;">​</a></h3><p>To the left of each paragraph, the gutter carries small marks:</p><ul><li><strong>The sentence meter.</strong> One tick per sentence, its width following the sentence&#39;s length in words. Sentences of ten words or more are a shade darker, and those of twenty-five or more darker still, so a paragraph&#39;s rhythm shows before you read it.</li><li><strong>Comment dots.</strong> A dot when the paragraph carries one of your own comments from the note, and a dot in another colour when it carries an open comment of Leathercase&#39;s.</li><li><strong>Thread marks.</strong> Where a directed thread plants something or pays it off on a quoted sentence, a mark just above that sentence shows <code>▲</code> for a plant and <code>▼</code> for a payoff or a reversal, with the thread&#39;s name and words such as <strong>Subplot: The ledger: plant, paid off in The vestry</strong> or <strong>Subplot: The lens: payoff, planted in The tower</strong>. A plant with no payoff yet says <strong>no payoff yet</strong>. Click the mark and the page jumps to the other end: from the plant to its payoff, or back.</li><li><strong>Gauge marks.</strong> For a thread drawn with a scale, such as the sample&#39;s theme &quot;What do we owe the drowned?&quot;, each scene where the thread moves ends with a mark carrying the thread&#39;s name, the word it reached and the running total, for example <code>Theme: What do we owe the drowned?: doubt -1</code> at the end of The cottage. Hover it for the charge of that scene and whether the line crosses zero there.</li></ul><p>Only stops anchored to a quoted sentence get a thread mark; a stop on a whole scene is too coarse a place for a mark. How to anchor stops is on the <a href="/guide/guide/threads">threads</a> page, and below under <a href="#anchor-a-stop-here">Anchor a stop here</a>.</p><p><img src="'+l+'" alt="The page beside The tower in chapter one: the sentence meter in the gutter, ▲ plant marks for The lens and The ledger above their sentences, and the theme&#39;s gauge mark at the end of The cottage" width="675" height="829" loading="lazy"></p><h2 id="selecting-a-passage" tabindex="-1">Selecting a passage <a class="header-anchor" href="#selecting-a-passage" aria-label="Permalink to &quot;Selecting a passage&quot;">​</a></h2><p>Click a sentence and it is selected, with a soft highlight. Click the same sentence again and the selection clears. Drag across text to take in more than one sentence, even across paragraphs of the same note. Neither a click nor a drag leaves the app or touches the file.</p><p>The keys move the selection a paragraph at a time:</p><table tabindex="0"><thead><tr><th>Key</th><th>Does</th></tr></thead><tbody><tr><td>click</td><td>selects a sentence</td></tr><tr><td><code>↑</code> <code>↓</code></td><td>the previous or next paragraph (its first sentence)</td></tr><tr><td><code>Alt+↑</code> <code>Alt+↓</code></td><td>the previous or next chapter</td></tr><tr><td><code>Home</code> <code>End</code></td><td>the first or last paragraph of the book</td></tr><tr><td><code>Enter</code> or <code>Ctrl/Cmd+Enter</code></td><td>opens the passage in its app</td></tr><tr><td><code>Ctrl/Cmd+J</code></td><td>the next broken anchor</td></tr><tr><td><code>L</code></td><td>the next lens</td></tr><tr><td><code>Esc</code></td><td>closes the review, then clears the selection, then turns the lens off</td></tr></tbody></table><p>The footer names these keys; press <code>?</code> for the full list in a small panel. Keys never fire while you type in a field.</p>',42)),a(o,{name:"manuscript-select",caption:"Clicking a sentence in The cottage, then walking down with the arrow keys while the side column follows"}),e[1]||(e[1]=t('<h2 id="the-side-column" tabindex="-1">The side column <a class="header-anchor" href="#the-side-column" aria-label="Permalink to &quot;The side column&quot;">​</a></h2><p>The side column on the right tells you what the story knows about the selected passage. Toggle it with <code>Ctrl/Cmd+B</code> or the side column button at the right of the head. Its sections, top to bottom:</p><h3 id="passage" tabindex="-1">Passage <a class="header-anchor" href="#passage" aria-label="Permalink to &quot;Passage&quot;">​</a></h3><p>Before you pick anything it says: &quot;Click a sentence to select it; drag to take in more. The column shows what the story knows about it, and opens it in your app.&quot;</p><p>With a passage selected it shows the passage in quotation marks (long passages cut at 160 characters), with the chapter and paragraph number as the section&#39;s hint, such as <code>The Night the Lamp Went Out · ¶ 3</code>. Under it:</p><table tabindex="0"><thead><tr><th>Control</th><th>Does</th></tr></thead><tbody><tr><td><strong>Open in</strong> and the app&#39;s name, such as <strong>Open in Obsidian</strong> (or <strong>Open in your default app</strong>)</td><td>Opens the file in your writing app at the passage. <code>Ctrl ↵</code> is printed on the button. See <a href="#open-in-your-own-app">Open in</a>.</td></tr><tr><td><strong>Show file in folder</strong></td><td>Opens your file manager with the passage&#39;s file selected.</td></tr><tr><td><strong>Copy passage</strong></td><td>Puts the selected text on the clipboard; the button reads <strong>Copied</strong> after.</td></tr><tr><td><strong>Comment on this passage</strong></td><td>Opens the comment composer. See <a href="/guide/guide/comments">Comments and word lists</a>.</td></tr><tr><td><strong>Anchor a stop here…</strong></td><td>Opens the form that anchors a thread stop on the selected sentence. Shown only when one paragraph is selected, the passage is inside a scene the grid knows, and the story has a thread of your own.</td></tr></tbody></table><p>The comments already on the selected paragraphs are listed below these, with <strong>Resolve</strong> and <strong>Remove</strong> for Leathercase&#39;s own.</p><p><img src="'+p+'" alt="The side column with a sentence of The tower selected: the quoted passage, Open in Visual Studio Code with the line saying why that app, Show file in folder, Copy passage, Comment on this passage, Anchor a stop here…, then Sentence log, Threads here and Scene" width="375" height="895" loading="lazy"></p><h3 id="sentence-log" tabindex="-1">Sentence log <a class="header-anchor" href="#sentence-log" aria-label="Permalink to &quot;Sentence log&quot;">​</a></h3><p>The sentences of the selected paragraph that you rewrote or cut in earlier sittings, each struck through with the day and what replaced it, and <strong>Copy</strong> to take one back by hand. See <a href="/guide/guide/sentence-log">Sentence log</a>.</p><h3 id="threads-here" tabindex="-1">Threads here <a class="header-anchor" href="#threads-here" aria-label="Permalink to &quot;Threads here&quot;">​</a></h3><p>Every thread that has a stop in the selected scene, one per line, with the stop&#39;s glyph, its role (<strong>plant</strong>, <strong>touch</strong>, <strong>payoff</strong>, <strong>reversal</strong>, or an arc&#39;s <strong>want</strong>, <strong>lie</strong>, <strong>turn</strong>, <strong>truth</strong>) and an audit mark. A thread whose stop is on this very passage shows brighter than the others. Hover a line for the stop&#39;s note. With none it says <strong>No thread stops in this scene.</strong></p><p>The glyphs are the same everywhere in Leathercase:</p><table tabindex="0"><thead><tr><th>Glyph</th><th>Means</th></tr></thead><tbody><tr><td>hollow triangle</td><td>a plant</td></tr><tr><td>filled triangle</td><td>a payoff</td></tr><tr><td>turned triangle</td><td>a reversal</td></tr><tr><td>dot</td><td>any other stop</td></tr><tr><td>tick in a green ring</td><td><strong>verified</strong>: the stop&#39;s quoted sentence was found in the scene</td></tr><tr><td><code>!</code> in a rose ring</td><td><strong>broken</strong>: the quote no longer matches the scene</td></tr><tr><td>dashed ring</td><td><strong>plan</strong>: the stop has no quote yet</td></tr></tbody></table><h3 id="scene" tabindex="-1">Scene <a class="header-anchor" href="#scene" aria-label="Permalink to &quot;Scene&quot;">​</a></h3><p>The scene&#39;s facts: <strong>POV</strong>, <strong>Time</strong> and <strong>Place</strong>, as the grid has them (<strong>not set</strong> or <strong>none found</strong> when they are missing). When characters are on stage it adds <strong>On stage: Nora Vidal, Bastian Kell.</strong>, and for each character whose arc has no stop in the scene, a line such as <strong>Inés Roca’s arc has no stop in this scene.</strong></p><h3 id="lens" tabindex="-1">Lens <a class="header-anchor" href="#lens" aria-label="Permalink to &quot;Lens&quot;">​</a></h3><p>The list of lenses, one at a time: <strong>No lens</strong>, <strong>Rhythm</strong>, <strong>Style checks</strong>, <strong>Dialogue</strong>, <strong>Echoes</strong>, <strong>Words</strong>, <strong>Accents</strong>. With a lens on and a paragraph selected, <strong>What the lens found</strong> lists every mark the lens made in that paragraph, with its note. Every lens is explained in <a href="/guide/guide/lenses">Lenses and style checks</a>. The footer at the bottom of the view also names the lens in force (<code>lens: style checks</code>); click it to step to the next.</p><h3 id="all-comments" tabindex="-1">All comments <a class="header-anchor" href="#all-comments" aria-label="Permalink to &quot;All comments&quot;">​</a></h3><p>Every comment of the book in one list, chapter by chapter. See <a href="/guide/guide/comments">Comments and word lists</a>.</p><h2 id="open-in-your-own-app" tabindex="-1">Open in your own app <a class="header-anchor" href="#open-in-your-own-app" aria-label="Permalink to &quot;Open in your own app&quot;">​</a></h2><p>The manuscript is read here and written elsewhere. <strong>Open in</strong> takes you from a passage straight to that place in the software you write in. Select a passage, then click the <strong>Open in</strong> button, press <code>Enter</code>, or press <code>Ctrl/Cmd+Enter</code>.</p><p>Leathercase goes as far into the file as the app allows:</p><table tabindex="0"><thead><tr><th>App reach</th><th>What happens</th></tr></thead><tbody><tr><td><strong>opens at line</strong></td><td>The app opens on the passage&#39;s paragraph.</td></tr><tr><td><strong>opens at heading</strong></td><td>The app opens at the scene heading above it.</td></tr><tr><td><strong>opens file</strong></td><td>The app opens the file at its start.</td></tr></tbody></table><p>Which app it uses is decided in this order: the app you chose for the story, then the app you chose for every story in that format on this machine, then an app Leathercase can infer, and last your system&#39;s default. When Leathercase inferred the app, a line under the button says why and where to change it, for example <strong>Inferred from the vault; choose another in Settings › Sources</strong>, <strong>Inferred from .scriv</strong>, or <strong>The only app here that opens .docx</strong>.</p><p>The first time you open a story whose app was never chosen, and several apps on this computer could open it, the column asks instead: <strong>Open this story in…</strong> lists the apps with how far each reaches, and the line &quot;These apps on this computer open .md files. The choice is kept with the story.&quot; Pick one, leave <strong>Use for every story in .md</strong> ticked if you want the same app for all your Markdown stories, and click <strong>Open in</strong> with the app&#39;s name. The story&#39;s choice is kept in its settings; the choice for every story is kept in this machine&#39;s preferences. Change either later in <strong>Settings › Sources</strong>.</p>',26)),a(o,{name:"manuscript-open-in",caption:"Selecting a sentence in The tower: Open in names the app, here the only one on this computer that opens .md, with the line saying why it was chosen"}),e[2]||(e[2]=t('<h3 id="open-the-whole-story" tabindex="-1">Open the whole story <a class="header-anchor" href="#open-the-whole-story" aria-label="Permalink to &quot;Open the whole story&quot;">​</a></h3><p><code>Ctrl+Shift+O</code> (<code>Cmd+Shift+O</code> on macOS) opens the story itself in your software, wherever you are in Leathercase. It is also <strong>Open the story in your software</strong> in the story&#39;s <code>⋯</code> menu in the sidebar, in the story&#39;s menu in the breadcrumb, and in the command palette. A file that is not a document, such as a folder, is shown in your file manager instead; Leathercase never runs a file.</p><h2 id="anchor-a-stop-here" tabindex="-1">Anchor a stop here <a class="header-anchor" href="#anchor-a-stop-here" aria-label="Permalink to &quot;Anchor a stop here&quot;">​</a></h2><p>A thread stop can be anchored on the exact sentence where the thread moves, from the page. Select one sentence, click <strong>Anchor a stop here…</strong>, then fill the small form:</p><table tabindex="0"><thead><tr><th>Field</th><th>What it is</th></tr></thead><tbody><tr><td><strong>Thread</strong></td><td>One of your own threads (the grid&#39;s POV and Time columns are not offered).</td></tr><tr><td><strong>Role</strong></td><td><strong>touch</strong>, <strong>plant</strong>, <strong>payoff</strong> or <strong>reversal</strong>.</td></tr><tr><td><strong>What the thread does here</strong></td><td>A short note for the stop.</td></tr></tbody></table><p>Click <strong>Anchor the stop</strong>. Leathercase writes the stop, with the selected sentence as its quote, to <code>StoryThreads.md</code> in your suite folder, never into your chapter. The status line at the foot of the page confirms it, such as <strong>Anchored The ledger at The tower</strong>, with <strong>Undo</strong>.</p><h2 id="broken-anchors" tabindex="-1">Broken anchors <a class="header-anchor" href="#broken-anchors" aria-label="Permalink to &quot;Broken anchors&quot;">​</a></h2><p>An anchor is a quoted sentence that ties a thread stop to its place in the prose. When you rewrite that sentence in your own app, the quote no longer matches and the anchor is broken. The page helps you put it right.</p><p>Press <code>Ctrl/Cmd+J</code>. When nothing is broken, the status line says <strong>No broken anchors: every quoted stop is found in its scene.</strong> Otherwise a <strong>Review</strong> section opens at the top of the side column, with its count (<code>1 of 3</code>), and the page scrolls to the scene:</p><ul><li><strong>Anchor no longer matches</strong>, then the thread, the role and the scene, such as <code>The ledger · plant · The tower</code>.</li><li><strong>Was</strong>: the old quote.</li><li><strong>Closest now</strong>: the sentence of the scene that shares the most words with it, highlighted on the page. When none shares a word: <strong>No sentence of the scene shares its words.</strong></li><li>A line on how much changed: <strong>Most of the quote&#39;s words are still there: this looks like an edit to the same moment.</strong>, or <strong>Much of the wording changed. Check the stop still holds before anchoring it again.</strong>, or, when the quote is gone, <strong>The quote is gone from the scene. Keep the stop as a plan until the moment is written again, or remove it.</strong></li></ul><p>Three buttons settle it:</p><table tabindex="0"><thead><tr><th>Button</th><th>Does</th></tr></thead><tbody><tr><td><strong>Anchor to the new passage</strong></td><td>Re-anchors the stop on the closest sentence now.</td></tr><tr><td><strong>Keep as a plan, no anchor</strong></td><td>Keeps the stop, without a quote.</td></tr><tr><td><strong>Remove the stop</strong></td><td>Takes the stop out of the thread.</td></tr></tbody></table><p>Each writes <code>StoryThreads.md</code> only. <code>Ctrl/Cmd+J</code> again goes to the next broken anchor; <code>Esc</code> closes the review. The review closes by itself when the last one is dealt with.</p>',13)),a(o,{name:"manuscript-review",caption:"Ctrl+J opens the review of a broken anchor, shows the closest sentence now, and Anchor to the new passage settles it"}),e[3]||(e[3]=t('<h2 id="undo-and-redo" tabindex="-1">Undo and redo <a class="header-anchor" href="#undo-and-redo" aria-label="Permalink to &quot;Undo and redo&quot;">​</a></h2><p>Everything the page writes (a comment made, resolved, reopened or removed, a stop anchored, re-anchored, kept as a plan or removed) goes on one undo stack. The status line at the foot of the page names the last step, such as <strong>Commented on ¶ 3 of The Night the Lamp Went Out</strong>, with <strong>Undo</strong> and the number of steps in the stack; <strong>Redo</strong> appears after an undo. Before anything is done it reads <strong>Comments go to Comments.md in your suite folder; your notes are never written.</strong></p><p>An undo writes the file back only if it still holds what Leathercase wrote. If the file changed outside Leathercase in the meantime, nothing is written and the status line says <strong>The file changed outside Leathercase since; nothing was written, and the step was dropped.</strong></p><h2 id="when-the-page-is-empty" tabindex="-1">When the page is empty <a class="header-anchor" href="#when-the-page-is-empty" aria-label="Permalink to &quot;When the page is empty&quot;">​</a></h2><p>A story with no prose yet shows: &quot;No chapter yet. The manuscript is every note that is not a character, a place or a thing, in the order of the folder tree; write one and it appears here.&quot; Since file roles, that means every file declared as the story&#39;s prose: a chapter written where nothing claims it waits, unsorted, on <a href="/guide/guide/how-a-story-is-read#unsorted">How this story is read</a> until you say it is prose. Write a chapter in your app; Leathercase watches the story&#39;s folder while the story is open, so the page shows the chapter soon after you save it.</p><h2 id="what-leathercase-writes" tabindex="-1">What Leathercase writes <a class="header-anchor" href="#what-leathercase-writes" aria-label="Permalink to &quot;What Leathercase writes&quot;">​</a></h2><p>The manuscript page writes only Leathercase&#39;s own files, in the story&#39;s suite folder:</p><table tabindex="0"><thead><tr><th>File</th><th>When</th></tr></thead><tbody><tr><td><code>Comments.md</code></td><td>A comment made, resolved, reopened or removed on the page.</td></tr><tr><td><code>StoryThreads.md</code></td><td>A stop anchored, re-anchored, kept as a plan or removed.</td></tr><tr><td><code>WordLists.md</code></td><td>A word put in or taken out of a word list from the words lens.</td></tr><tr><td><code>Accents.md</code></td><td>A word given to a character from the accents lens.</td></tr></tbody></table><p>Your chapters are only ever read.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/guide/lenses">Lenses and style checks</a></li><li><a href="/guide/guide/comments">Comments and word lists</a></li><li><a href="/guide/guide/sentence-log">Sentence log</a></li><li><a href="/guide/guide/threads">Threads</a></li><li><a href="/guide/guide/export">Export</a></li></ul>',11))])}const v=s(g,[["render",u]]);export{T as __pageData,v as default};
